import {
  KanbanRoot,
  KanbanBoard,
  type KanbanCardBase,
  type KanbanColumnBase,
} from "@/components/bevelui/kanban";

type Task = KanbanCardBase & {
  title: string;
  priority: "low" | "medium" | "high";
};

type Column = KanbanColumnBase<Task>;

const initialColumns: Column[] = [
  { id: "todo",       title: "To Do",       cards: [...] },
  { id: "inprogress", title: "In Progress", cards: [...] },
  { id: "done",       title: "Done",        cards: [...] },
];

export function MyBoard() {
  const [columns, setColumns] = React.useState(initialColumns);

  return (
    <KanbanRoot<Task, Column>
      columns={columns}
      onColumnsChange={setColumns}
      renderCard={(task, column, { isDragging }) => (
        <div
          className={cn(
            "rounded-xl border border-border bg-card p-3",
            isDragging && "opacity-40",
          )}
        >
          <p className="text-sm font-medium">{task.title}</p>
        </div>
      )}
    >
      <KanbanBoard />
    </KanbanRoot>
  );
}

type Lead = KanbanCardBase & {
  company: string;
  value: number;
  owner: string;
};

type Stage = KanbanColumnBase<Lead> & {
  target: number;  // monthly revenue target
};

<KanbanRoot<Lead, Stage>
  columns={stages}
  onCardMove={(lead, from, to) => {
    // Update lead stage in your CRM
    updateLead(lead.id, { stage: to });
  }}
  renderCard={(lead) => (
    <LeadCard lead={lead} />
  )}
  renderColumnHeader={(stage, { cardCount }) => (
    <StageHeader
      stage={stage}
      count={cardCount}
      totalValue={sumValue(stage.cards)}
    />
  )}
>
  <KanbanBoard />
</KanbanRoot>

type Candidate = KanbanCardBase & {
  name: string;
  role: string;
  score?: number;
};

// useKanban() works inside KanbanRoot for custom sidebar panels
function ApplicantCount() {
  const { columns } = useKanban<Candidate>();
  const total = columns.reduce((n, c) => n + c.cards.length, 0);
  return <span>{total} applicants</span>;
}

